/* setresgid(rgid, egid, sgid) */

gid_t new_r = 1000;
gid_t new_e = 2000;
gid_t new_s = 3000;
int ret;

// Privileged: Set all three IDs to arbitrary values
ret = setresgid(new_r, new_e, new_s);

// Unprivileged: Drop effective GID, retain Real and Saved GIDs
// (new_e must match current Real, Effective, or Saved GID)
ret = setresgid(-1, new_e, -1);

// Use -1 to keep the ID unchanged
ret = setresgid(new_r, -1, new_s);

// Success: 0
// Failure: -1 (EPERM if insufficient privilege/invalid ID)
